const src = $json.body || $json || {};
const rows = Array.isArray(src.messages) ? src.messages : [src];

function normalizeLeakText(value) {
  return String(value || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase();
}

function internalLeakReasons(value) {
  const raw = String(value || '');
  const text = normalizeLeakText(raw);
  const checks = [
    ['json_schema_parser_instruction', /you must format your output|json schema|schema instance|provided schema|parsed and type-checked|type-checked according to|trailing commas|enclosing markdown codeblock|well-formatted instance|annotate and validate json documents|declarative language/i],
    ['structured_output_parser_instruction', /structured output parser|output parser|format instructions|must adhere to|adhere to the provided schema|include the enclosing markdown codeblock/i],
    ['internal_prompt_leak', /system prompt|developer message|tool call|internal instruction|do not reveal|no reveles|mensaje del sistema/i],
    ['schema_shape_leak', /["']\$schema["']|["']required["']\s*:\s*\[|["']properties["']\s*:\s*\{|properties\}\}/i],
  ];
  return checks.filter(([, regex]) => regex.test(raw) || regex.test(text)).map(([reason]) => reason);
}

return rows.map((row, idx) => {
  const conversationId = Number(row.conversation_id || row.chatwoot_conv_id || row.id || 0);
  if (!conversationId) throw new Error('conversation_id is required at index ' + idx);
  const content = String(row.content || '').trim();
  if (!content) throw new Error('content is required at index ' + idx);
  const privateMessage = row.private === true || String(row.private || '').toLowerCase() === 'true';
  const leakReasons = privateMessage ? [] : internalLeakReasons(content);
  if (leakReasons.length) {
    throw new Error('public_content_blocked_internal_leak at index ' + idx + ': ' + leakReasons.join(','));
  }
  return {
    json: {
      conversation_id: conversationId,
      account_id: Number(row.account_id || src.account_id || 2),
      base_url: String(row.base_url || src.base_url || 'http://chatwoot:3000').replace(/\/$/, ''),
      content,
      private: privateMessage,
    }
  };
});

const requests = $('Code - Normalize Messages').all().map(item => item.json || {});
const responses = $input.all();
const results = responses.map((item, index) => {
  const request = requests[index] || {};
  const response = item.json || {};
  const body = response.body && typeof response.body === 'object' ? response.body : response;
  const statusCode = Number(response.statusCode || response.status || body.statusCode || body.status || 0);
  const ok = statusCode >= 200 && statusCode < 300 && !body.error;
  return {
    ok,
    conversation_id: request.conversation_id || body.conversation_id || body.conversation?.id || body.data?.conversation_id || null,
    message_id: body.id || body.data?.id || null,
    private: request.private ?? body.private ?? body.data?.private ?? null,
    http_status: statusCode || null,
    status: body.status || body.data?.status || null,
    error: body.error || body.message || null,
  };
});
const failed = results.filter(row => !row.ok);
return [{ json: {
  ok: failed.length === 0,
  count: results.length,
  sent_count: results.filter(row => row.ok).length,
  failed_count: failed.length,
  results,
} }];
